Network Interface Status:&#34; &gt;&gt; $DIAGNOSTIC_LOG netstat -i &gt;&gt; $DIAGNOSTIC_LOG # 检查路由表 echo -e &#34;
Routing Table:&#34; &gt;&gt; $DIAGNOSTIC_LOG netstat -rn &gt;&gt; $DIAGNOSTIC_LOG # 检查监听端口 echo -e &#34;
Listening Ports:&#34; &gt;&gt; $DIAGNOSTIC_LOG netstat -ltn &gt;&gt; $DIAGNOSTIC_LOG # 检查已建立连接 echo -e &#34;
